class Reading:
    def __init__(self, value):
        self.value = value

class Sensor:
    def __init__(self, name):
        self.name = name
        self.readings = []

    def add(self, reading):
        if isinstance(reading, Reading):
            self.readings.append(reading)

east = Sensor("East")
east.add(Reading(21))
print(east.name, east.readings[0].value)
